<script>
  var P = window.PHONE_APP || {};
  var calls = (P.data && P.data.recentCalls) || [];
  var voicemails = (P.data && P.data.voicemails) || [];
  var charBirthday = (P.data && P.data.charBirthday) || "0325";
  var dialRules = (P.data && P.data.dialRules) || {};

  var e = function (s) {
    return String(s == null ? "" : s).replace(/[&<>]/g, function (c) {
      return {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;"
      }[c];
    });
  };

  /* 兜底数据，防止没有数据时页面空白 */
  if (calls.length === 0) {
    calls = [{
      name: "小公主",
      location: "中国",
      time: "10:31",
      isMissed: false,
      detail: "通话时长 3分20秒"
    }];
  }

  if (voicemails.length === 0) {
    voicemails = [{
      number: "10086",
      date: "今天",
      duration: "00:15",
      transcription: "AI 忘记生成留言了，这是系统兜底的测试留言。"
    }];
  }

  /* 拨号规则兜底 */
  if (!dialRules["110"]) dialRules["110"] = "打这个干什么？想让我被抓走吗？";
  if (!dialRules["120"]) dialRules["120"] = "打这个干什么？我身体好着呢！";
  if (!dialRules["911"]) dialRules["911"] = "打这个干什么？这里又不是美国！";
  if (!dialRules["12315"]) dialRules["12315"] = "打这个干什么？要投诉我吗？";
  if (!dialRules["520"]) dialRules["520"] = "（80字温柔心声）想和你一起看遍四季变换，直到白发苍苍。";
  if (!dialRules["birthday"]) dialRules["birthday"] = "（80字大胆心声）其实我每天晚上都在想你，想把你紧紧抱在怀里。";

  /* 渲染最近通话 */
  document.getElementById("call-list").innerHTML = calls.map(function (c) {
    var nameClass = c.isMissed ? "call-name missed" : "call-name";
    var arrowHtml = c.isMissed ? '<span class="arrow">↘</span>' : "";

    return '<div class="list-item">' +
      '<div class="call-icon">👤</div>' +
      '<div class="call-info">' +
        '<div class="' + nameClass + '">' + e(c.name) + '</div>' +
        '<div class="call-location">' + arrowHtml + " " + e(c.location) + '</div>' +
      '</div>' +
      '<div class="call-time">' + e(c.time) + '</div>' +
      '<div class="info-btn">i</div>' +
    '</div>';
  }).join("");

  /* 渲染语音留言 */
  document.getElementById("voicemail-list").innerHTML = voicemails.map(function (v, index) {
    return '<div class="list-item" style="position:relative;" onclick="openVmModal(' + index + ')">' +
      '<div class="vm-dot"></div>' +
      '<div class="vm-content">' +
        '<div class="vm-header">' +
          '<div class="vm-number">' + e(v.number) + '</div>' +
          '<div class="vm-date">' + e(v.date) + '</div>' +
        '</div>' +
        '<div style="display:flex;justify-content:space-between;align-items:center;">' +
          '<div class="vm-transcription">' + e(v.transcription) + '</div>' +
          '<div class="vm-duration">' + e(v.duration) + '</div>' +
        '</div>' +
      '</div>' +
      '<div class="vm-icon">▶️</div>' +
    '</div>';
  }).join("");

  /* 打开语音留言详情 */
  function openVmModal(index) {
    var v = voicemails[index];
    if (!v) return;

    document.getElementById("vm-modal-number").innerText = v.number || "未知号码";
    document.getElementById("vm-modal-meta").innerText =
      (v.date || "未知日期") + " · " + (v.duration || "未知时长");
    document.getElementById("vm-modal-text").innerText =
      v.transcription || "暂无留言转写内容";

    document.getElementById("vm-modal").classList.add("active");
  }

  /* 关闭语音留言详情 */
  function closeVmModal(ev) {
    if (ev && ev.target !== document.getElementById("vm-modal")) return;
    document.getElementById("vm-modal").classList.remove("active");
  }

  /* 拨号键盘逻辑 */
  var currentNumber = "";
  var displayEl = document.getElementById("number-text");
  var birthdayErrorCount = 0;

  function inputNumber(num) {
    if (currentNumber.length >= 15) return;
    currentNumber += num;
    displayEl.innerText = currentNumber;
  }

  function clearNumber() {
    currentNumber = "";
    displayEl.innerText = "";
  }

  function makeCall() {
    if (currentNumber === "") return;

    var content = "";
    var title = "拨出中...";
    var meta = "正在连接...";

    if (
      currentNumber === "110" ||
      currentNumber === "120" ||
      currentNumber === "911" ||
      currentNumber === "12315"
    ) {
      content = dialRules[currentNumber] || "打这个干什么？";
      title = "通话已接通";
      meta = "对方接听了";
    } else if (currentNumber === "520") {
      content = dialRules["520"];
      title = "接通了TA的心声";
      meta = "温柔模式";
    } else if (currentNumber === charBirthday) {
      content = dialRules["birthday"];
      title = "接通了TA的隐秘想法";
      meta = "火热模式";
      birthdayErrorCount = 0;
    } else {
      if (currentNumber.length === 4 && /^\d{4}$/.test(currentNumber)) {
        birthdayErrorCount++;

        if (birthdayErrorCount >= 3) {
          content = "你是在找我的生日吗？\n\n笨蛋，是 " +
            charBirthday +
            " 啦！\n\n（顺便说一句，输错3次就会提醒，别再试啦~）";
          title = "😏 被我发现了吧";
          meta = "生日提示";
          birthdayErrorCount = 0;
        } else {
          content = "（嘟...嘟...嘟...）\n\n您拨打的号码是空号，或者暂时无法接通。\n\n角色：咦？我拨错了吗？挂了吧。";
          title = "无法接通";
          meta = "空号或无法接通";
        }
      } else {
        content = "（嘟...嘟...嘟...）\n\n您拨打的号码是空号，或者暂时无法接通。\n\n角色：咦？我拨错了吗？挂了吧。";
        title = "无法接通";
        meta = "空号或无法接通";
      }
    }

    document.getElementById("call-modal-title").innerText = title;
    document.getElementById("call-modal-meta").innerText = meta;
    document.getElementById("call-modal-text").innerText = content;
    document.getElementById("call-modal").classList.add("active");
  }

  /* 关闭拨号弹窗 */
  function closeCallModal(ev) {
    if (ev && ev.target !== document.getElementById("call-modal")) return;

    document.getElementById("call-modal").classList.remove("active");
    clearNumber();
  }

  /* ==================================================
     底部导航切换：修复语音留言按钮 ID 不匹配
     calls      -> tab-calls / page-calls
     dial       -> tab-dial / page-dial
     voicemails -> tab-vm / page-voicemails
     ================================================== */
  function switchTab(tab) {
    var tabId;
    var pageId;
    var title;
    var showSearch = true;
    var navBtnText = "编辑";

    if (tab === "calls") {
      tabId = "tab-calls";
      pageId = "page-calls";
      title = "最近通话";
    } else if (tab === "dial") {
      tabId = "tab-dial";
      pageId = "page-dial";
      title = "拨号键盘";
      showSearch = false;
      navBtnText = "清除";
    } else if (tab === "voicemails") {
      /* 关键修复：语音留言按钮实际 ID 是 tab-vm */
      tabId = "tab-vm";
      pageId = "page-voicemails";
      title = "语音留言";
    } else {
